import json,pathlib,copy
from bs4 import BeautifulSoup
r=pathlib.Path('work/research-2026');p=json.load(open(r/'reviewed.json'));xs=json.load(open(r/'verified-sites162-next100-review.json'));before={};dec=[]
assert not (r/'featured162-before.json').exists()
fix={30:'Develops protective coatings for industrial and military components exposed to wear, corrosion and friction.',36:'Develops software for application building, AI orchestration, cybersecurity and cloud operations.',48:'Grows sugarcane and produces refined sugar.',54:'A 700-acre mixed-use real-estate development in Vineyard, Utah.',56:'Develops ultraviolet air- and surface-treatment systems.',58:'Provides education and coaching about VA disability claims. Its website states that its employees are not VA-accredited claims representatives.',82:'Provides defense technology and tactical training, including drone systems.',85:'Develops jet engines and aerospace propulsion technology for subsonic, supersonic and hypersonic applications.'}
special={29:'Official United Family Advocates body describes family-preservation and child-welfare policy advocacy.',30:'Official United Protective Technologies body names United Protective Technologies, LLC and describes protective coatings. Performance claims are not independently established.',36:'Official US AI body describes computing and cybersecurity software. Security and compliance guarantees are not independently validated.',39:'Official U.S. Black Chambers, Inc. body identifies support and advocacy for Black-owned businesses and its chamber network.',44:'Official US Medicare PH body identifies US Medicare Philippines, Inc. and Medicare-portability advocacy. Proposed changes are not treated as current benefit eligibility.',48:'Official U.S. Sugar body describes farming and refined-sugar production. Market-share and sustainability claims are not independently verified.',49:'Official U.S. Wheat Associates About body explicitly describes export-market development and says it does not buy, sell or process wheat. Placeholder Latin office text is ignored.',54:'Official Utah City body explicitly describes a 700-acre downtown development in Vineyard, Utah. It is not a municipal government; planned infrastructure is not established completed work.',55:'Official UTS Systems body describes mobile shelters, power and climate-control infrastructure.',56:'Official UV Angel About body describes ultraviolet treatment products and explicitly disclaims health claims for the surface system. Clinical infection-prevention benefits are not independently established.',58:'Official VA Claims Insider, LLC body describes coaching and explicitly states its employees are not accredited agents, VSOs, attorneys or recognized VA entities. Benefit outcomes are not independently verified.',60:'Official Valley Fund Corporation body identifies residential and vocational services for people with developmental disabilities and gives EIN 95-3422002.',66:'Official Vanguard Charitable body explicitly identifies Vanguard Charitable Endowment Program as an independent 501(c)(3), distinct from The Vanguard Group.',75:'Official Vapor Technology Association body describes vapor-industry advocacy. Its displayed death counter and health/legal claims are not independent evidence.',76:'Official VARCOMM About body explicitly identifies VARCOMM Holdings, Inc. and its telecom-company relationship. Operating-company ownership statements are not automatically transferred to all group entities.',77:'Official Varda Space Industries body describes orbital materials research, manufacturing platforms and reentry testing.',78:'Official Varex body identifies Varex Imaging Corporation and X-ray components for medical, security and industrial systems.',80:'Official Vatn Systems body describes autonomous underwater vehicles. Contested-water performance and military endorsement are not independently established.',81:'Official Vaya body names Vaya Defense & Space, Inc. and describes hybrid propulsion development in Cocoa, Florida. Safety and sustainability claims are not independently verified.',82:'Official Vector body identifies defense technology and training. Military approvals and combat-performance claims are not independently established.',83:'Official Vector Remote Care body describes remote cardiac-device monitoring software. Claimed clinical and efficiency outcomes are not independently verified.',85:'Official Velontra body describes subsonic, supersonic and hypersonic propulsion development.',89:'Official Venture Medical body explicitly names Venture Medical, LLC and describes wound-care supplies and operational software. Clinical effectiveness is not independently verified.',91:'Official Venus Aerospace body identifies Venus Aerospace Corp. and describes rotating-detonation and ramjet development. Efficiency records and flight performance are not independently validated.',93:'Official Verisma body names Verisma Systems, Inc. and describes health-information management.',94:'Official Verituity body identifies Verituity, Inc. and payment/payee verification software. Fraud prevention and compliance claims are not independently established.',95:'Official Vertanical body describes cannabinoid-based chronic-pain therapeutic development. Efficacy and regulatory status are not independently established.'}
for n,v in enumerate(xs):
 if v['decision']!='confirmed' or n<24 or n in [42,72,97]:continue
 i=v['id'];assert p[i]['name']==v['original_name'] and p[i]['review_outcome']!='confirmed';before[i]=copy.deepcopy(p[i]);note=special.get(n,'Official organization body text identifies this organization and supports the activity summarized. Existing ownership evidence is retained without inferring additional ownership from its name.')
 p[i].update(description=fix.get(n,v['description']),notes=note,identity_evidence=note,review_outcome='confirmed',checked_at='2026-09-13',as_of='2026-09-13')
 

 if n==66:p[i]['ownership']='Nonprofit'
 e=v['fetched_evidence'][0];assert e['http_status']==200
 s=BeautifulSoup(open(e['cache_path']).read(),'html.parser')
 for t in s(['script','style','nav','header']):t.decompose()
 body=' '.join(s.stripped_strings)
 ss={s['url']:s for s in p[i]['sources']};ss[e['url']]={'url':e['url'],'label':'Official organization evidence','claim':note};p[i]['sources']=list(ss.values());dec.append(dict(id=i,name=p[i]['name'],decision='confirmed',notes=note,fetched_evidence=v['fetched_evidence'],reviewed_body=body))
(r/'featured162-before.json').write_text(json.dumps(before,indent=2)+'\n');(r/'featured162-decisions.json').write_text(json.dumps(dec,indent=2)+'\n')
(r/'featured162-deferred.json').write_text(json.dumps([dict(id=xs[n]['id'],name=xs[n]['original_name'],reason=why) for n,why in [(42,'Press-release index only; inspect substantive organization or article body.'),(72,'Vantor Holdings named as trademark owner; holding-company history and operating scope not established.'),(97,'Leadership biographies do not fully establish proposed organizational activity.')]],indent=2)+'\n')
for f in [r/'reviewed.json',pathlib.Path('outputs/2026-research-trial/profiles.json')]:f.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
pathlib.Path('lobbying-map/research/reviewed-2026.json').write_text(json.dumps(p,ensure_ascii=False));print(len(dec),'identity confirmations saved')
